#include "driver_ragdoll.hpp"
#include <btBulletDynamicsCommon.h>
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(int argc,char**argv){try{Resources r(argc>1?argv[1]:"/tmp/ofo049-data");auto d=load_native_driver(r);auto joints=native_driver_joints(d);int hinges=0;for(auto&j:joints)hinges+=j.hinge;need(joints.size()==10&&hinges==4,"Native ten joints and four hinges");need(joints[0].parent==6&&joints[0].child==5,"Native head to torso joint identity");need(joints[3].limit1[0]<-1.2f&&joints[3].limit1[1]==0,"Native asymmetric elbow limit");btDefaultCollisionConfiguration config;btCollisionDispatcher dispatch(&config);btDbvtBroadphase broad;btSequentialImpulseConstraintSolver solver;btDiscreteDynamicsWorld world(&dispatch,&broad,&solver,&config);world.setGravity(btVector3(0,-9.81f,0));world.getSolverInfo().m_numIterations=20;btBoxShape groundShape(btVector3(100,1,100));btRigidBody::btRigidBodyConstructionInfo ci(0,nullptr,&groundShape);btRigidBody ground(ci);btTransform floor;floor.setIdentity();floor.setOrigin(btVector3(0,-1,0));ground.setWorldTransform(floor);world.addRigidBody(&ground);auto placement=load_driver_placement(r,1,load_geometry(r,"cars/car_1/body.bgm"));auto pose=sample_driver_pose(d,placement);auto car=multiply(translate({0,4,0}),rotate_y(.7f));{NativeDriverRagdoll rag(world,d,pose,car,{0,1,8},{0,.2f,0},80);need(world.getNumCollisionObjects()==12&&world.getNumConstraints()==10,"11 original segments and10 native constraints");auto initial=rag.snapshot();for(size_t i=0;i<11;i++){auto expected=multiply(car,pose.parts[i]);for(int k=0;k<16;k++)need(std::abs(expected[k]-initial[i][k])<1e-5f,"Launch transforms preserve native seated pose");}auto geometry=make_driver_geometry(d);for(int tick=0;tick<600;tick++){world.stepSimulation(1.f/120,1,1.f/120);auto now=rag.snapshot();auto skinned=driver_ragdoll_pose(d,now);deform_driver(d,skinned,geometry);for(auto&m:now)for(auto v:m)need(std::isfinite(v),"Finite native ragdoll step");for(auto&j:joints){auto a=point(skinned.skin[j.parent],d.segments[j.anchor_bone].joint),b=point(skinned.skin[j.child],d.segments[j.anchor_bone].joint);need(length(a-b)<.45f,"Native joint anchors stay connected");}}rag.apply_impulse({1,1,1});rag.set_velocity({0,0,0});float mass=0;for(auto*b:rag.bodies())mass+=1/b->getInvMass();need(std::abs(mass-80)<1e-3f,"Configured total driver mass normalized from source weights");}need(world.getNumCollisionObjects()==1&&world.getNumConstraints()==0,"Ragdoll cleanup removes all Bullet resources");world.removeRigidBody(&ground);std::cout<<"11 native driver bodies/10 joints:600 physics steps, connected anchors, skin continuity and cleanup passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
